1	/** Closed recovery commands and redacted durable facts. No model or OS effects. */
2	import { createHash } from "node:crypto";
3	import { types } from "node:util";
4	import type { ExecutionSafetyCapabilities, ExecutionSafetyCapabilityName, ProcessCleanupStatus } from "./execution-safety-contracts.js";
5	
6	export const EXCEPTIONAL_PROCESS_STATES = ["orphaned", "identity_mismatch", "backend_unavailable", "outcome_unknown"] as const;
7	export type RecoveryAction = "inspect" | "terminate" | "remove_owned_artifact";
8	export interface RecoveryScope {
9	  kind: "subprocess" | "streaming"; runId: string; invocationId: string; logicalProcessId: string;
10	  taskId?: string; sessionId?: string; revision: number; ownerId: string; fencingToken: number;
11	  rootPid?: number; state: string; backendIdentity: string; birthFingerprint: string;
12	}
13	export interface RecoveryTarget {
14	  scope: RecoveryScope; owned: boolean; pendingEffects: boolean;
15	  capabilities: ExecutionSafetyCapabilities; cleanup: ProcessCleanupStatus;
16	}
17	export interface RecoveryProposal {
18	  version: 1; proposalId: string; callId: string; scope: RecoveryScope; requestedAction: RecoveryAction;
19	  targetScope: readonly string[]; requestedCapabilities: readonly ExecutionSafetyCapabilityName[];
20	  expiresAt: string; rationale: string;
21	}
22	export type RecoveryState = "proposed" | "user_decision_required" | "authorized" | "executing" | "executed" | "rejected" | "failed" | "outcome_unknown";
23	export type RecoveryReason = "submitted" | "validated" | "destructive_requires_user" | "user_approved" | "user_denied" |
24	  "scope_changed" | "expired" | "execution_started" | "inspection_completed" | "cleanup_verified" |
25	  "effect_failed" | "effect_outcome_unknown" | "model_failed";
26	export interface RecoveryAuditRecord extends Omit<RecoveryProposal, "rationale"> {
27	  proposalFingerprint: string; commandFingerprint: string; argumentsFingerprint: string; rationaleFingerprint: string;
28	  createdAt: string; updatedAt: string; state: RecoveryState; reason: RecoveryReason; attemptId?: string;
29	  observation?: "running" | "exited" | "identity_mismatch" | "outcome_unknown";
30	  cleanupState?: ProcessCleanupStatus["state"];
31	}
32	export class ProcessRecoveryError extends Error {
33	  constructor(readonly code: string) { super(RECOVERY_ERROR_MESSAGES[code] ?? "Exceptional recovery was refused."); this.name = "ProcessRecoveryError"; }
34	}
35	const RECOVERY_ERROR_MESSAGES: Readonly<Record<string, string>> = Object.freeze({
36	  invalid_recovery_proposal: "Recovery proposal is not a supported closed command.",
37	  routine_recovery_forbidden: "Routine process lifecycle never accepts AI recovery commands.",
38	  recovery_scope_mismatch: "Recovery proposal no longer matches the exact recorded process and call.",
39	  recovery_expired: "Recovery proposal has expired or its deadline is invalid.",
40	  recovery_approval_required: "This exact destructive recovery proposal requires a local-user decision.",
41	  recovery_identity_unavailable: "A complete process birth and backend identity could not be verified.",
42	  recovery_ownership_unavailable: "The exact process ownership lease is not available to this Runner.",
43	  recovery_outcome_unknown: "An earlier recovery effect has an unresolved outcome; it will not be replayed.",
44	  recovery_capability_unavailable: "The required semantic recovery capability is not enforced.",
45	  recovery_action_unsupported: "No trusted ownership recipe exists for that recovery action.",
46	  recovery_model_failed: "The exceptional proposal generator failed; no recovery command was executed.",
47	  recovery_not_found: "Recovery proposal does not exist for this run.",
48	});
49	export function recoveryFingerprint(value: unknown): string {
50	  return createHash("sha256").update(canonical(value)).digest("hex");
51	}
52	function canonical(value: unknown): string {
53	  if (Array.isArray(value)) return "[" + value.map(canonical).join(",") + "]";
54	  if (value && typeof value === "object") return "{" + Object.entries(value).filter(([,v]) => v !== undefined)
55	    .sort(([a],[b]) => a.localeCompare(b)).map(([k,v]) => JSON.stringify(k) + ":" + canonical(v)).join(",") + "}";
56	  return JSON.stringify(value);
57	}
58	export function recoveryScope(target: RecoveryTarget): RecoveryScope { return parseRecoveryScope(target.scope); }
59	export function sameRecoveryScope(left: RecoveryScope, right: RecoveryScope): boolean {
60	  // Never PID-only: birth, backend, lease fence and every invocation owner matter.
61	  return recoveryFingerprint(left) === recoveryFingerprint(right);
62	}
63	export function isExceptionalProcessState(state: string): boolean {
64	  return (EXCEPTIONAL_PROCESS_STATES as readonly string[]).includes(state);
65	}
66	const scopeKeys = ["kind", "runId", "invocationId", "logicalProcessId", "taskId", "sessionId", "revision", "ownerId", "fencingToken", "rootPid", "state", "backendIdentity", "birthFingerprint"];
67	export function parseRecoveryScope(value: unknown): RecoveryScope {
68	  const p = closed(value, scopeKeys);
69	  if (p.kind !== "subprocess" && p.kind !== "streaming") invalid();
70	  for (const k of ["runId", "invocationId", "logicalProcessId", "ownerId", "state", "backendIdentity", "birthFingerprint"]) text(p[k]);
71	  for (const k of ["taskId", "sessionId"]) if (p[k] !== undefined) text(p[k]);
72	  if (!Number.isSafeInteger(p.revision) || (p.revision as number) < 0 || !Number.isSafeInteger(p.fencingToken) || (p.fencingToken as number) < 1) invalid();
73	  if (p.rootPid !== undefined && (!Number.isSafeInteger(p.rootPid) || (p.rootPid as number) < 1)) invalid();
74	  return Object.freeze({ ...p }) as unknown as RecoveryScope;
75	}
76	const proposalKeys = ["version", "proposalId", "callId", "scope", "requestedAction", "targetScope", "requestedCapabilities", "expiresAt", "rationale"];
77	const capabilities = ["tree_termination", "crash_cleanup", "verified_emptiness", "write_confinement"];
78	export function parseRecoveryProposal(value: unknown): RecoveryProposal {
79	  const p = closed(value, proposalKeys);
80	  if (p.version !== 1) invalid();
81	  text(p.proposalId); text(p.callId); text(p.rationale, 4096);
82	  if (!["inspect", "terminate", "remove_owned_artifact"].includes(p.requestedAction as string)) invalid();
83	  if (!Array.isArray(p.targetScope) || p.targetScope.length < 1 || p.targetScope.length > 16) invalid();
84	  const targets = p.targetScope.map(v => text(v));
85	  if (!Array.isArray(p.requestedCapabilities) || p.requestedCapabilities.length > 4 || new Set(p.requestedCapabilities).size !== p.requestedCapabilities.length) invalid();
86	  if (p.requestedCapabilities.some(v => !capabilities.includes(v as string))) invalid();
87	  date(p.expiresAt);
88	  return Object.freeze({ ...p, scope: parseRecoveryScope(p.scope), targetScope: Object.freeze(targets),
89	    requestedCapabilities: Object.freeze([...p.requestedCapabilities]) }) as unknown as RecoveryProposal;
90	}
91	export function makeRecoveryAudit(proposal: RecoveryProposal, at: string): RecoveryAuditRecord {
92	  const { rationale, ...safe } = proposal;
93	  const fingerprints = { commandFingerprint: recoveryFingerprint(proposal.requestedAction),
94	    argumentsFingerprint: recoveryFingerprint({ targetScope: proposal.targetScope, requestedCapabilities: proposal.requestedCapabilities }),
95	    rationaleFingerprint: recoveryFingerprint(rationale) };
96	  return { ...safe, ...fingerprints, proposalFingerprint: recoveryFingerprint({ ...safe, rationaleFingerprint: fingerprints.rationaleFingerprint }),
97	    createdAt: at, updatedAt: at, state: "proposed", reason: "submitted" };
98	}
99	export function parseRecoveryAuditRecord(value: unknown): RecoveryAuditRecord {
100	  const p = closed(value, [...proposalKeys.filter(k => k !== "rationale"), "proposalFingerprint", "commandFingerprint", "argumentsFingerprint", "rationaleFingerprint", "createdAt", "updatedAt", "state", "reason", "attemptId", "observation", "cleanupState"]);
101	  const proposal = parseRecoveryProposal(Object.fromEntries(proposalKeys.map(k => [k, k === "rationale" ? "redacted" : p[k]])));
102	  for (const k of ["proposalFingerprint", "commandFingerprint", "argumentsFingerprint", "rationaleFingerprint"])
103	    if (typeof p[k] !== "string" || !/^[a-f0-9]{64}$/.test(p[k] as string)) invalid();
104	  date(p.createdAt); date(p.updatedAt);
105	  if (!["proposed", "user_decision_required", "authorized", "executing", "executed", "rejected", "failed", "outcome_unknown"].includes(p.state as string)) invalid();
106	  if (!["submitted", "validated", "destructive_requires_user", "user_approved", "user_denied", "scope_changed", "expired", "execution_started", "inspection_completed", "cleanup_verified", "effect_failed", "effect_outcome_unknown", "model_failed"].includes(p.reason as string)) invalid();
107	  if (p.attemptId !== undefined) text(p.attemptId);
108	  if (p.observation !== undefined && !["running", "exited", "identity_mismatch", "outcome_unknown"].includes(p.observation as string)) invalid();
109	  if (p.cleanupState !== undefined && !["not_required", "pending", "verified_empty", "failed"].includes(p.cleanupState as string)) invalid();
110	  const { rationale: _r, ...safe } = proposal;
111	  if (p.commandFingerprint !== recoveryFingerprint(p.requestedAction) ||
112	      p.argumentsFingerprint !== recoveryFingerprint({ targetScope: p.targetScope, requestedCapabilities: p.requestedCapabilities }) ||
113	      p.proposalFingerprint !== recoveryFingerprint({ ...safe, rationaleFingerprint: p.rationaleFingerprint })) invalid();
114	  return Object.freeze({ ...p, scope: proposal.scope, targetScope: proposal.targetScope,
115	    requestedCapabilities: proposal.requestedCapabilities }) as unknown as RecoveryAuditRecord;
116	}
117	export function validateRecoveryTransition(prior: RecoveryAuditRecord | undefined, next: RecoveryAuditRecord, actor: { role: string; id: string }, at: string): void {
118	  const runner = actor.role === "runner" && actor.id === "process-recovery";
119	  const user = actor.role === "user" && actor.id === "local-user";
120	  if (next.updatedAt !== at || Date.parse(next.createdAt) > Date.parse(at)) invalid();
121	  if (!prior) { if (!runner || next.state !== "proposed" || next.reason !== "submitted" || next.createdAt !== at) invalid(); return; }
122	  const mutable = ["state", "reason", "updatedAt", "attemptId", "observation", "cleanupState"];
123	  const immutable = (r: RecoveryAuditRecord) => Object.fromEntries(Object.entries(r).filter(([k]) => !mutable.includes(k)));
124	  if (recoveryFingerprint(immutable(prior)) !== recoveryFingerprint(immutable(next)) || Date.parse(at) < Date.parse(prior.updatedAt)) invalid();
125	  const transitions: Record<RecoveryState, readonly RecoveryState[]> = {
126	    proposed: ["authorized", "user_decision_required", "rejected", "failed"], user_decision_required: ["authorized", "rejected"],
127	    authorized: ["executing", "rejected"], executing: ["executed", "failed", "outcome_unknown", "rejected"],
128	    executed: [], rejected: [], failed: [], outcome_unknown: [],
129	  };
130	  if (!transitions[prior.state].includes(next.state)) invalid();
131	  const approval = prior.state === "user_decision_required";
132	  if (approval ? (!user && !(runner && next.state === "rejected")) : !runner) invalid();
133	  if (next.state === "authorized" && ((next.requestedAction !== "inspect" && (!user || next.reason !== "user_approved")) || Date.parse(at) >= Date.parse(next.expiresAt))) invalid();
134	  if (next.state === "user_decision_required" && (next.requestedAction !== "terminate" || next.reason !== "destructive_requires_user")) invalid();
135	  if (next.state === "executing" && (!next.attemptId || prior.attemptId || next.reason !== "execution_started" || Date.parse(at) >= Date.parse(next.expiresAt))) invalid();
136	  if (prior.attemptId && next.attemptId !== prior.attemptId) invalid();
137	  if (next.state === "executed" && (next.requestedAction === "inspect" ? next.reason !== "inspection_completed" : next.reason !== "cleanup_verified" || next.cleanupState !== "verified_empty")) invalid();
138	}
139	export function recoveryBlocksRun(records: Readonly<Record<string, RecoveryAuditRecord>> | undefined): boolean {
140	  return Object.values(records ?? {}).some(r => ["user_decision_required", "executing", "outcome_unknown"].includes(r.state) || (r.state === "authorized" && r.requestedAction !== "inspect"));
141	}
142	function closed(value: unknown, keys: readonly string[]): Record<string, unknown> {
143	  if (!value || typeof value !== "object" || Array.isArray(value) || types.isProxy(value) || ![null, Object.prototype].includes(Object.getPrototypeOf(value))) invalid();
144	  const result: Record<string, unknown> = {};
145	  for (const key of Reflect.ownKeys(value)) {
146	    if (typeof key !== "string" || !keys.includes(key)) invalid();
147	    const descriptor = Object.getOwnPropertyDescriptor(value, key)!;
148	    if (!("value" in descriptor)) invalid();
149	    result[key] = descriptor.value;
150	  }
151	  return result;
152	}
153	function invalid(): never { throw new ProcessRecoveryError("invalid_recovery_proposal"); }
154	function text(value: unknown, max = 512): string {
155	  if (typeof value !== "string" || !value.trim() || value.length > max || /[\u0000-\u001f]/.test(value)) invalid();
156	  return value;
157	}
158	function date(value: unknown): void {
159	  if (typeof value !== "string" || value.length > 64 || !Number.isFinite(Date.parse(value))) invalid();
160	}
