342	function createCleanupOnlyOwner(options: {
343	  readonly backend: BackpressuredProcessBackend;
344	  readonly binding: ProcessBackendBinding;
345	  readonly fence: ProcessEffectFence;
346	  readonly onReleased: (owned: RunnerInternalOwnedProcess) => void;
347	}): RunnerInternalOwnedProcess {
348	  let cleanupPromise: Promise<Readonly<{ exitCode?: number; signal?: string }>> | undefined;
349	  let cleanupResult: Readonly<{ exitCode?: number; signal?: string }> | undefined;
350	  const unavailable = async () => {
351	    throw new Error("Runner internal process channel acquisition did not complete.");
352	  };
353	  const owned: RunnerInternalOwnedProcess = Object.freeze({
354	    rootPid: options.binding.rootPid,
355	    binding: options.binding,
356	    setOutputSink: () => () => undefined,
357	    write: unavailable,
358	    closeInput: unavailable,
359	    async reconcile() {
360	      return parseProcessReconciliation(
361	        await options.backend.reconcile(options.binding, options.fence),
362	      );
363	    },
364	    async closeVerified(input: Parameters<RunnerInternalOwnedProcess["closeVerified"]>[0]) {
365	      if (cleanupResult) return cleanupResult;
366	      if (cleanupPromise) return await cleanupPromise;
367	      positiveTimeout(input.shutdownTimeoutMs, "shutdown timeout");
368	      const timeoutMs = positiveTimeout(input.terminationTimeoutMs, "termination timeout");
369	      const attempt = (async () => {
370	        await cleanupExactBackend(options.backend, options.binding, options.fence, timeoutMs);
371	        const result = Object.freeze({});
372	        options.onReleased(owned);
373	        return result;
374	      })();
375	      cleanupPromise = attempt;
376	      try {
377	        cleanupResult = await attempt;
378	        return cleanupResult;
379	      } catch (error) {
380	        if (cleanupPromise === attempt) cleanupPromise = undefined;
381	        throw error;
382	      }
383	    },
384	  });
385	  return owned;
386	}
387	
388	async function cleanupExactBackend(
389	  backend: BackpressuredProcessBackend,
390	  binding: ProcessBackendBinding,
391	  fence: ProcessEffectFence,
392	  timeoutMs: number,
393	): Promise<void> {
394	  const deadline = Date.now() + timeoutMs;
395	  let observed = parseProcessReconciliation(await backend.reconcile(binding, fence));
396	  while (observed.state !== "exited" && Date.now() < deadline) {
397	    try { parseProcessSignalResult(await backend.signal(binding, "force_terminate", fence)); }
398	    catch {}
399	    observed = parseProcessReconciliation(await backend.reconcile(binding, fence));
400	    if (observed.state !== "exited") await delay(POLL_INTERVAL_MS);
401	  }
402	  if (observed.state !== "exited") throw new Error("Runner internal failed-launch cleanup is unverified.");
403	  let empty = parseProcessEmptyVerification(await backend.verifyEmpty(binding, fence));
404	  while (!empty.empty && Date.now() < deadline) {
405	    await delay(POLL_INTERVAL_MS);
406	    empty = parseProcessEmptyVerification(await backend.verifyEmpty(binding, fence));
407	  }
408	  if (!empty.empty) throw new Error("Runner internal failed-launch cleanup could not prove emptiness.");
409	  parseProcessReleaseResult(await backend.release(binding, fence));
410	}
411	
412	async function waitForTerminal(
413	  backend: ProcessBackend,
414	  binding: ProcessBackendBinding,
415	  fence: ProcessEffectFence,
416	  deadline: number,
417	): Promise<ProcessReconciliation> {
418	  let observed = parseProcessReconciliation(await backend.reconcile(binding, fence));
419	  while (observed.state !== "exited" && Date.now() < deadline) {
420	    await delay(POLL_INTERVAL_MS);
421	    observed = parseProcessReconciliation(await backend.reconcile(binding, fence));
422	  }
423	  return observed;
424	}
425	
426	function asBackpressured(backend: ProcessBackend): BackpressuredProcessBackend {
427	  if (typeof (backend as Partial<BackpressuredProcessBackend>)
428	    .backpressuredChannelProvider !== "function") {
429	    throw new Error("Runner internal process backend lacks a backpressured channel.");
430	  }
431	  return backend as BackpressuredProcessBackend;
432	}
433	
434	function boundedIdentity(value: string, label: string): string {
435	  if (typeof value !== "string" || !value || value.includes("\0") ||
436	      Buffer.byteLength(value) > 512) {
437	    throw new Error(`Runner internal ${label} is invalid.`);
438	  }
439	  return value;
440	}
441	
442	function positiveTimeout(value: number, label: string): number {
443	  if (!Number.isSafeInteger(value) || value < 1 || value > 3_600_000) {
444	    throw new Error(`Runner internal ${label} is invalid.`);
445	  }
446	  return value;
447	}
448	
449	function delay(milliseconds: number): Promise<void> {
450	  return new Promise((resolveDelay) => setTimeout(resolveDelay, milliseconds));
451	}
