  ],
  cleaned: ["backendBinding", "stopIntent", "observation", "output", "result"],
  launch_not_proven: ["result"],
  orphaned: ["stopIntent"],
  identity_mismatch: ["backendBinding", "stopIntent"],
  backend_unavailable: [
    "backendBinding",
    "stopIntent",
    "observation",
    "output",
  ],
  outcome_unknown: ["backendBinding", "stopIntent", "observation", "output"],
  cleanup_blocked: [
    "backendBinding",
