      const state = requiredEnum(
        data.state,
        new Set<
          | "orphaned"
          | "identity_mismatch"
          | "backend_unavailable"
          | "outcome_unknown"
          | "cleanup_blocked"
        >([
          "orphaned",
          "identity_mismatch",
          "backend_unavailable",
          "outcome_unknown",
          "cleanup_blocked",
        ]),
        "failure state",
      );
      return moveDerived(
        {
          ...base,
          ...(data.cleanup === undefined
            ? {}
            : { cleanup: parseCleanup(data.cleanup) }),
          ...(data.result === undefined
            ? {}
            : { result: parseResult(data.result) }),
          ...(data.output === undefined
            ? {}
