}
function compareRetry(
  existing: DurableSubprocessRecord,
  incoming: DurableSubprocessRecord,
): DurableSubprocessRecord {
  if (
    existing.requestFingerprint !== incoming.requestFingerprint ||
    existing.retryKey !== incoming.retryKey
