function moveDerived(
  current: DurableSubprocessRecord,
  state: DurableSubprocessState,
  at: string,
  reason?: string,
): DurableSubprocessRecord {
  return {
    ...current,
    state,
    history: [...current.history, { state, at, ...(reason ? { reason } : {}) }],
