    record.escalation.length > 0 &&
    ![
      "stopping",
      "exited",
      "verifying_empty",
      "cleaned",
      "backend_unavailable",
      "identity_mismatch",
      "outcome_unknown",
      "cleanup_blocked",
    ].includes(record.state)
