  assertKeys(
    o,
    new Set([
      "inheritedNames",
      "removedNames",
      "explicitSafeNames",
      "grantedNames",
    ]),
    "environment audit",
  );
  return {
    inheritedNames: strings(o.inheritedNames),
    removedNames: strings(o.removedNames),
    explicitSafeNames: strings(o.explicitSafeNames),
