        data.action,
        new Set<ProcessEscalationAction>([
          "interrupt",
          "terminate",
          "force_terminate",
        ]),
        "action",
      );
      const outcome = requiredEnum(
        data.outcome,
        new Set<"running" | "exited" | "failed">([
          "running",
          "exited",
          "failed",
        ]),
        "outcome",
      );
