          | "backend_unavailable"
          | "outcome_unknown"
          | "cleanup_blocked"
        >([
          "orphaned",
          "identity_mismatch",
          "backend_unavailable",
          "outcome_unknown",
          "cleanup_blocked",
        ]),
        "failure state",
      );
      return moveDerived(
        {
          ...base,
          ...(data.cleanup === undefined
            ? {}
