  if (
    record.state === "cleanup_blocked" &&
    (!record.result ||
      record.cleanup.state !== "failed" ||
      !resultMatches(record))
  )
    throw new Error(
      "Durable process record in cleanup_blocked requires consistent failed cleanup and result.",
