      "exited",
      "verifying_empty",
      "cleaned",
      "backend_unavailable",
      "identity_mismatch",
      "outcome_unknown",
      "cleanup_blocked",
    ].includes(record.state)
  )
    throw new Error("Durable process escalation history is invalid.");
