const BASE_KEYS = [
  "schemaVersion",
  "revision",
  "logicalProcessId",
  "invocationId",
  "runId",
  "taskId",
  "sessionId",
  "requestFingerprint",
  "retryKey",
  "ownerId",
  "fencingToken",
  "leaseExpiresAt",
  "outputOwnerId",
  "outputPrepared",
  "state",
  "history",
  "requiredCapabilities",
  "environmentAudit",
  "escalation",
  "cleanup",
  "pendingEffect",
  "pendingEffects",
  "emptyVerification",
  "mutations",
];
const OPTIONAL_BY_STATE: Record<DurableSubprocessState, readonly string[]> = {
  prepared: ["stopIntent", "outputPrepareFailure"],
  launching: ["stopIntent"],
  running: ["backendBinding"],
  stopping: ["backendBinding", "stopIntent"],
  exited: ["backendBinding", "stopIntent", "observation"],
  verifying_empty: [
    "backendBinding",
