    if (!record.backendBinding) return false;
    try {
      if (record.state === "cleanup_blocked") await this.reconcileRecord(record);
      else await this.escalate(record);
    } catch {
      return false;
    }
    return true;
  }

  async reconcileStartup(): Promise<ReconciliationOutcome[]> {
    const outcomes: ReconciliationOutcome[] = [];
    for (const invocationId of this.options.store.listRowIds()) {
      let snapshot: DurableSubprocessRecord;
      try {
        const decoded = this.options.store.readByInvocation(invocationId);
        if (!decoded) continue;
        snapshot = decoded;
      } catch {
        outcomes.push({ invocationId, state: "corrupt" });
        continue;
      }
      if (
        ![
          "prepared",
          "launching",
          "running",
          "stopping",
          "exited",
          "verifying_empty",
          "backend_unavailable",
          "cleanup_blocked",
        ].includes(snapshot.state)
      )
        continue;
      if (snapshot.pendingEffects.length > 0) {
        outcomes.push({
          invocationId,
          state: "effect_outcome_unresolved",
        });
        continue;
      }
      if (
        snapshot.state === "cleanup_blocked" &&
        !snapshot.backendBinding &&
        snapshot.result?.outcome !== "launch_failed"
      )
        continue;
      const leaseIsLive =
        Date.parse(snapshot.leaseExpiresAt) >
        this.options.clock.now().getTime();
      if (snapshot.state === "launching" && !snapshot.backendBinding) {
        if (leaseIsLive) {
          outcomes.push({ invocationId, state: "leased" });
          continue;
        }
        try {
          snapshot = this.writer.apply({
            type: "orphan_unbound_launch",
            invocationId,
            expectedRevision: snapshot.revision,
            ownerId: snapshot.ownerId,
            fencingToken: snapshot.fencingToken + 1,
            at: this.now(),
            detail: "Restart found launch without durable identity.",
          });
        } catch {}
        let current: DurableSubprocessRecord | undefined;
        try {
          current = this.options.store.readByInvocation(invocationId);
        } catch {}
        outcomes.push({
          invocationId,
          state: current?.state ?? "corrupt",
        });
        continue;
      }
      try {
        const owned = this.takeRecoveryOwnership(snapshot);
        if (!owned) {
          outcomes.push({ invocationId, state: "leased" });
          continue;
        }
        snapshot = owned;
        await this.reconcileRecord(snapshot);
      } catch (error) {
        await this.classifyReconciliationFailure(snapshot, error);
      }
      let current: DurableSubprocessRecord | undefined;
      try {
        current = this.options.store.readByInvocation(snapshot.invocationId);
      } catch {}
      outcomes.push({
        invocationId: snapshot.invocationId,
        state: current?.state ?? "corrupt",
      });
    }
    return outcomes;
  }

  async recoverExceptional(
    request: ExceptionalRecoveryRequest,
  ): Promise<ExceptionalRecoveryObservation> {
    if (request.action !== "inspect" && request.action !== "terminate")
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Exceptional recovery action is not supported.",
      );
    if (request.action === "terminate" && request.userApproved !== true)
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Exceptional termination requires an exact local-user approval.",
      );
    const record = this.options.store.readByInvocation(request.invocationId);
    if (!record)
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Exceptional recovery target does not exist.",
      );
    if (!EXCEPTIONAL_RECOVERY_STATES.has(record.state))
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        `Routine process state ${record.state} never accepts exceptional recovery.`,
      );
    if (
      record.runId !== request.runId ||
      record.logicalProcessId !== request.logicalProcessId ||
      record.taskId !== request.taskId ||
      record.sessionId !== request.sessionId ||
      record.revision !== request.expectedRevision ||
      record.ownerId !== request.ownerId ||
      record.fencingToken !== request.fencingToken
    )
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Exceptional recovery scope no longer matches the durable record.",
      );
    if (record.pendingEffects.length > 0)
      throw new SubprocessRuntimeError(
        "outcome_unknown",
        "An earlier native effect is unresolved; it is never guessed or replayed.",
      );
    const binding = record.backendBinding;
    if (!binding)
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "No durable backend identity exists for this process; recovery is refused.",
      );
    const identityProof = durableBackendIdentityFingerprint(binding);
    if (
      identityProof !== request.backendIdentityFingerprint ||
      durableBirthFingerprint(binding) !== request.birthFingerprint
    )
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Recorded backend or birth identity does not match the validated proposal.",
      );
    request.assertGrant?.();
    const owned = this.takeRecoveryOwnership(record);
    if (!owned)
      throw new SubprocessRuntimeError(
        "outcome_unknown",
        "The exact process ownership lease is not available to this Runner.",
      );
    // Live backend identity proof: exact re-attestation only. Adoption would
    // change the implementation digest and is never an identity proof.
    const selected = await this.fencedEffect(record.invocationId, (fence) =>
      reattestProcessBackend(this.options.registry, binding, fence),
    );
    if (
      selected.registryId !== binding.registryId ||
      selected.implementationGeneration !== binding.implementationGeneration ||
      selected.implementationDigest !== binding.implementationDigest ||
      selected.attestationDigest !== binding.attestationDigest
    )
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Live backend attestation does not match the recorded binding.",
      );
    let observed = await this.observeExceptional(
      record.invocationId,
      identityProof,
      "backend_reconcile",
      async (fence) =>
        parseProcessReconciliation(
          await selected.backend.reconcile(binding, fence),
        ).state,
    );
    if (request.action === "inspect")
      return this.exceptionalResult(request.invocationId, observed, identityProof);
    if (observed === "identity_mismatch" || observed === "outcome_unknown")
      return this.exceptionalResult(request.invocationId, observed, identityProof);
    for (const action of ["terminate", "force_terminate"] as const) {
      if (observed === "exited") break;
      request.assertGrant?.();
      observed = await this.observeExceptional(
        record.invocationId,
        identityProof,
        "backend_signal",
        async (fence) =>
          parseProcessSignalResult(
            await selected.backend.signal(binding, action, fence),
          ).state,
      );
      if (observed === "exited") break;
      observed = await this.observeExceptional(
        record.invocationId,
        identityProof,
        "backend_reconcile",
        async (fence) =>
          parseProcessReconciliation(
            await selected.backend.reconcile(binding, fence),
          ).state,
      );
    }
    if (observed !== "exited")
      return this.exceptionalResult(request.invocationId, observed, identityProof);
    const verification = await this.fencedEffectJournaled(
      record.invocationId,
      "backend_verify_empty",
      (fence) => selected.backend.verifyEmpty(binding, fence),
    );
    const empty = parseProcessEmptyVerification(verification.result);
    if (!empty.empty) {
      // A failed emptiness proof is recorded as an observation, never as cleanup.
      const current = this.current(record.invocationId);
      this.mutate({
        type: "record_exceptional_observation",
        invocationId: record.invocationId,
        expectedRevision: current.revision,
        at: this.now(),
        effectId: verification.effectId,
        identityProof,
        outcome: "outcome_unknown",
      });
      return this.exceptionalResult(
        request.invocationId,
        "outcome_unknown",
        identityProof,
      );
    }
    const beforeCleanup = this.current(record.invocationId);
    this.mutate({
      type: "record_exceptional_cleanup",
      invocationId: record.invocationId,
      expectedRevision: beforeCleanup.revision,
      at: this.now(),
      effectId: verification.effectId,
      identityProof,
      verification: empty.proofArtifactId === undefined
        ? { empty: true }
        : { empty: true, proofArtifactId: empty.proofArtifactId },
    });
    return this.exceptionalResult(request.invocationId, "exited", identityProof);
  }

  /** Journals an exceptional native effect and durably records its outcome. */
  private async observeExceptional(
    invocationId: string,
    identityProof: string,
    family: "backend_reconcile" | "backend_signal",
    effect: (
      fence: ProcessEffectFence,
    ) => Promise<"running" | "exited" | "identity_mismatch" | "outcome_unknown">,
  ): Promise<"running" | "exited" | "identity_mismatch" | "outcome_unknown"> {
    const journal = await this.journaledEffect(invocationId, family, effect);
    const current = this.current(invocationId);
    this.mutate({
      type: "record_exceptional_observation",
      invocationId,
      expectedRevision: current.revision,
      at: this.now(),
      effectId: journal.effectId,
      identityProof,
      outcome: journal.result,
    });
    return journal.result;
  }

  private async fencedEffectJournaled<T>(
    invocationId: string,
    family: DurableProcessEffectFamily,
    effect: (fence: ProcessEffectFence) => Promise<T>,
  ): Promise<{ readonly result: T; readonly effectId: string }> {
    return await this.journaledEffect(invocationId, family, effect);
  }

  private exceptionalResult(
    invocationId: string,
    observation: "running" | "exited" | "identity_mismatch" | "outcome_unknown",
    identityProof: string,
  ): ExceptionalRecoveryObservation {
    const record = this.current(invocationId);
    return Object.freeze({
      invocationId,
      state: record.state,
      observation,
      cleanup: structuredClone(record.cleanup),
      identityProof,
      revision: record.revision,
    });
  }

  private async runClaimed(
    request: SnapshotInvocation,
    record: DurableSubprocessRecord,
  ): Promise<GenericProcessResult> {
    record = this.renew(record);
    let output: ProcessOutputSession;
    try {
      output = await this.fencedEffect(record.invocationId, (fence) =>
        this.options.outputs.prepare(record.outputOwnerId, fence),
      );
      record = this.current(record.invocationId);
      record = this.mutate({
        type: "mark_output_prepared",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
      });
    } catch (error) {
      record = this.current(record.invocationId);
      this.mutate({
        type: "record_output_prepare_failure",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        detail: "Recoverable output ownership could not be prepared.",
      });
      throw new SubprocessRuntimeError(
        "launch_not_proven",
        "Recoverable output ownership could not be prepared.",
        { cause: error },
      );
    }
    let grant: ConsumedExecutionGrant;
    try {
      grant = consumeGrant(
        this.options.grants,
        request.grantId,
        request.intent,
        this.options.clock.now(),
      );
    } catch (error) {
      await this.failBeforeLaunch(
        record,
        output,
        "Execution grant was invalid.",
      );
      throw error;
    }
    let preparedEnvironment;
    try {
      preparedEnvironment = this.options.environments.prepare({
        ambient: request.ambientEnvironment,
        explicitOverrides: request.explicitEnvironment,
        runId: request.intent.runId,
        invocationId: request.intent.invocationId,
        credentialGrantId: request.credentialGrantId,
      });
    } catch (error) {
      await this.failBeforeLaunch(
        record,
        output,
        "Child environment preparation failed.",
      );
      throw error;
    }
    const audit: DurableEnvironmentAudit = {
      inheritedNames: [...preparedEnvironment.audit.inheritedNames],
      removedNames: [...preparedEnvironment.audit.removedNames],
      explicitSafeNames: [...preparedEnvironment.audit.explicitSafeNames],
      grantedNames: [...preparedEnvironment.audit.grantedNames],
    };
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "record_environment",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      environmentAudit: audit,
    });
    record = this.applyCurrent(record, (revision) => ({
      type: "mark_launching",
      invocationId: record.invocationId,
      expectedRevision: revision,
      at: this.now(),
    }));
    let selected: SelectedProcessBackend;
    try {
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        selectProcessBackend(
          this.options.registry,
          request.intent.requestedCapabilities,
          fence,
        ),
      );
    } catch (error) {
      await this.failBeforeLaunch(
        record,
        output,
        "No verified backend satisfies invocation.",
      );
      throw new SubprocessRuntimeError(
        "backend_unavailable",
        "No verified backend satisfies invocation.",
        { cause: error },
      );
    }
    const stopPromise = this.stopTrigger(request);
    const launchPromise = this.fencedEffect(record.invocationId, (fence) =>
      this.options.environments.withChildEnvironment(
        preparedEnvironment.capability,
        (environment) =>
          selected.backend.launch(
            deepFreeze({
              intent: request.intent,
              grant,
              environment: snapshotChildEnvironment(environment),
              outputOwnerId: record.outputOwnerId,
              fence,
            }),
          ),
      ),
    );
    let rawLaunch: unknown;
    let first:
      { kind: "launch"; value: unknown } | { kind: "stop"; stop: StopTrigger };
    try {
      first = await Promise.race([
        Promise.resolve(launchPromise).then((value) => ({
          kind: "launch" as const,
          value,
        })),
        stopPromise.then((stop) => ({ kind: "stop" as const, stop })),
      ]);
    } catch (error) {
      const blocked = recoverableLaunchBlocker(error);
      if (blocked)
        return await this.persistLaunchCleanupBlocker(record, output, selected, blocked);
      await this.failBeforeLaunch(
        record,
        output,
        "Launch failed before identity was proven.",
      );
      throw new SubprocessRuntimeError(
        "launch_not_proven",
        "Process launch was not proven.",
        { cause: error },
      );
    }
    if (first.kind === "stop") {
      record = this.requestStopLatest(record.invocationId, first.stop.reason);
      try {
        rawLaunch = await launchPromise;
      } catch (error) {
        const blocked = recoverableLaunchBlocker(error);
        if (blocked)
          return await this.persistLaunchCleanupBlocker(record, output, selected, blocked);
        await this.failBeforeLaunch(
          record,
          output,
          "Launch did not return identity.",
        );
        throw new SubprocessRuntimeError(
          "launch_not_proven",
          "Process launch was not proven.",
          { cause: error },
        );
      }
    } else rawLaunch = first.value;
    let launch;
    try {
      launch = parseProcessLaunchResult(rawLaunch);
    } catch (error) {
      await this.failBeforeLaunch(record, output, "Malformed launch result.");
      throw new SubprocessRuntimeError(
        "launch_not_proven",
        "Process launch was not proven.",
        { cause: error },
      );
    }
    const binding: DurableBackendBinding = {
      registryId: selected.registryId,
      backendId: selected.attestation.backendId,
      implementationGeneration: selected.implementationGeneration,
      implementationDigest: selected.implementationDigest,
      attestationVersion: selected.attestation.attestationVersion,
      attestationDigest: selected.attestationDigest,
      ...launch,
    };
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "bind_launch",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      binding,
    });
    const observePromise = this.journaledEffect(
      record.invocationId,
      "backend_observe",
      (fence) =>
        selected.backend.observe(
          binding,
          async (stream, bytes) => {
            await output.write(stream, bytes, fence);
            request.onOutput?.(stream, new Uint8Array(bytes));
          },
          fence,
        ),
    );
    let observedJournal: Awaited<typeof observePromise>;
    let observation: ReturnType<typeof parseProcessObservation>;
    try {
      if (record.stopIntent) {
        await this.escalate(record);
        observedJournal = await observePromise;
      } else {
        const race = await Promise.race([
          Promise.resolve(observePromise).then((value) => ({
            kind: "observed" as const,
            value,
          })),
          stopPromise.then((stop) => ({ kind: "stop" as const, stop })),
        ]);
        if (race.kind === "stop") {
          record = this.requestStopLatest(
            record.invocationId,
            race.stop.reason,
          );
          await this.escalate(record);
          observedJournal = await observePromise;
        } else observedJournal = race.value;
      }
      observation = parseProcessObservation(observedJournal.result);
    } catch (error) {
      const current = this.current(record.invocationId);
      if (
        [
          "launching",
          "running",
          "stopping",
          "exited",
          "verifying_empty",
          "backend_unavailable",
        ].includes(current.state)
      )
        this.applyFailure(
          current,
          "backend_unavailable",
          "Process observation or termination failed.",
        );
      throw new SubprocessRuntimeError(
        "backend_unavailable",
        "Process observation or termination failed.",
        { cause: error },
      );
    }
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "record_exit",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      effectId: observedJournal.effectId,
      observation: {
        ...(observation.exitCode === undefined
          ? {}
          : { exitCode: observation.exitCode }),
        ...(observation.signal ? { signal: observation.signal } : {}),
        observedAt: this.now(),
      },
    });
    return await this.finish(record, output, selected);
  }

  private async persistLaunchCleanupBlocker(
    record: DurableSubprocessRecord,
    _output: ProcessOutputSession,
    selected: SelectedProcessBackend,
    blocked: { readonly launch: ReturnType<typeof parseProcessLaunchResult>; readonly detail: string },
  ): Promise<GenericProcessResult> {
    const binding: DurableBackendBinding = {
      registryId: selected.registryId,
      backendId: selected.attestation.backendId,
      implementationGeneration: selected.implementationGeneration,
      implementationDigest: selected.implementationDigest,
      attestationVersion: selected.attestation.attestationVersion,
      attestationDigest: selected.attestationDigest,
      ...blocked.launch,
    };
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "bind_launch",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      binding,
    });
    let detail = blocked.detail;
    try {
      const reconciliation = await this.reconcileBackend(
        record.invocationId,
        selected,
        binding,
      );
      const verified = await this.journaledEffect(
        record.invocationId,
        "backend_verify_empty",
        (fence) => selected.backend.verifyEmpty(binding, fence),
      );
      const verification = parseProcessEmptyVerification(verified.result);
      record = this.current(record.invocationId);
      this.mutate({
        type: "record_empty_verification",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        effectId: verified.effectId,
        verification,
      });
      detail = verification.empty
        ? `${detail} Backend reconciliation reported ${reconciliation.state}; retained binding requires explicit recovery.`
        : verification.detail === detail
          ? detail
          : `${detail} Backend verification: ${verification.detail}`;
    } catch (error) {
      detail = `${detail} Blocker reconciliation failed: ${error instanceof Error ? error.message : "unknown error"}`;
    }
    const at = this.now();
    const failed = this.applyFailure(record, "cleanup_blocked", detail, {
      state: "failed",
      failedAt: at,
      code: "launch_cleanup_blocked",
      detail,
    });
    return resultFromFailure(failed);
  }

  private async finish(
    record: DurableSubprocessRecord,
    output: ProcessOutputSession,
    selected?: SelectedProcessBackend,
  ): Promise<GenericProcessResult> {
    if (record.state === "exited") {
      let disposition: ProcessOutputDisposition[];
      let finalizeEffectId: string;
      try {
        const finalized = await this.journaledEffect(
          record.invocationId,
          "output_finalize",
          (fence) => output.finalize(fence),
        );
        disposition = outputDisposition(finalized.result);
        finalizeEffectId = finalized.effectId;
      } catch {
        const failed = this.applyFailure(
          record,
          "cleanup_blocked",
          "Output finalization failed.",
          {
            state: "failed",
            failedAt: this.now(),
            code: "output_finalize_failed",
            detail: "Recoverable output could not be finalized.",
          },
        );
        return resultFromFailure(failed);
      }
      record = this.current(record.invocationId);
      record = this.mutate({
        type: "begin_verify",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        effectId: finalizeEffectId,
        output: disposition,
      });
    }
    if (record.state !== "verifying_empty") return resultFromFailure(record);
    let binding = requiredBinding(record);
    let backend = selected;
    try {
      if (!backend) {
        try {
          backend = await this.fencedEffect(record.invocationId, (fence) =>
            reattestProcessBackend(this.options.registry, binding, fence),
          );
        } catch {
          backend = await this.fencedEffect(record.invocationId, (fence) =>
            adoptProcessBackendAfterRestart(
              this.options.registry,
              binding,
              fence,
            ),
          );
          record = this.mutate({
            type: "adopt_backend",
            invocationId: record.invocationId,
            expectedRevision: record.revision,
            at: this.now(),
            binding: {
              ...binding,
              registryId: backend.registryId,
              implementationGeneration: backend.implementationGeneration,
              implementationDigest: backend.implementationDigest,
              attestationVersion: backend.attestation.attestationVersion,
              attestationDigest: backend.attestationDigest,
            },
          });
          binding = requiredBinding(record);
        }
      }
    } catch (error) {
      this.applyFailure(
        record,
        "backend_unavailable",
        "Backend attestation changed before empty verification.",
      );
      throw new SubprocessRuntimeError(
        "backend_unavailable",
        "Backend attestation changed.",
        { cause: error },
      );
    }
    let verification = record.emptyVerification;
    if (!verification) {
      try {
        const verified = await this.journaledEffect(
          record.invocationId,
          "backend_verify_empty",
          (fence) => backend.backend.verifyEmpty(binding, fence),
        );
        verification = parseProcessEmptyVerification(verified.result);
        record = this.current(record.invocationId);
        record = this.mutate({
          type: "record_empty_verification",
          invocationId: record.invocationId,
          expectedRevision: record.revision,
          at: this.now(),
          effectId: verified.effectId,
          verification,
        });
      } catch {
        const failed = this.applyFailure(
          record,
          "cleanup_blocked",
          "Malformed empty verification.",
          {
            state: "failed",
            failedAt: this.now(),
            code: "empty_verification_invalid",
            detail: "Backend empty verification was invalid.",
          },
        );
        return resultFromFailure(failed);
      }
    }
    const finishedAt = this.now();
    if (!verification.empty) {
      const failed = this.applyFailure(
        record,
        "cleanup_blocked",
        verification.detail,
        {
          state: "failed",
          failedAt: finishedAt,
          code: "verified_empty_failed",
          detail: verification.detail,
        },
      );
      return resultFromFailure(failed);
    }
    let releaseEffectId: string;
    try {
      const fresh = await this.fencedEffect(record.invocationId, (fence) =>
        reattestProcessBackend(this.options.registry, binding, fence),
      );
      const released = await this.journaledEffect(
        record.invocationId,
        "backend_release",
        (fence) => fresh.backend.release(binding, fence),
      );
      parseProcessReleaseResult(released.result);
      releaseEffectId = released.effectId;
    } catch {
      const failed = this.applyFailure(
        record,
        "cleanup_blocked",
        "Backend release failed.",
        {
          state: "failed",
          failedAt: finishedAt,
          code: "backend_release_failed",
          detail: "Backend release was invalid or failed.",
        },
      );
      return resultFromFailure(failed);
    }
    const result = terminalResult(record, finishedAt);
    const cleanup: ProcessCleanupStatus = {
      state: "verified_empty",
      verifiedAt: finishedAt,
      ...(verification.proofArtifactId
        ? { proofArtifactId: verification.proofArtifactId }
        : {}),
    };
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "complete",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: finishedAt,
      effectId: releaseEffectId,
      cleanup,
      result,
    });
    return resultFromRecord(record);
  }

  private async escalate(snapshot: DurableSubprocessRecord): Promise<void> {
    const existing = this.termination.get(snapshot.invocationId);
    if (existing) return existing;
    const work = this.runEscalation(snapshot).finally(() =>
      this.termination.delete(snapshot.invocationId),
    );
    this.termination.set(snapshot.invocationId, work);
    return work;
  }
  private async runEscalation(
    snapshot: DurableSubprocessRecord,
  ): Promise<void> {
    let record = this.current(snapshot.invocationId);
    if (record.state === "backend_unavailable" && record.stopIntent)
      record = this.applyCurrent(record, (revision) => ({
        type: "request_stop",
        invocationId: record.invocationId,
        expectedRevision: revision,
        at: this.now(),
        reason: record.stopIntent!.reason,
      }));
    else if (
      record.state === "running" ||
      record.state === "backend_unavailable"
    )
      record = this.requestStopLatest(
        record.invocationId,
        record.stopIntent?.reason ?? "cancelled",
      );
    if (
      (record.state !== "stopping" && record.state !== "cleanup_blocked") ||
      !record.backendBinding
    ) return;
    const actions = ["interrupt", "terminate", "force_terminate"] as const;
    for (let index = 0; index < actions.length; index += 1) {
      record = this.current(record.invocationId);
      if (record.state !== "stopping" && record.state !== "cleanup_blocked") return;
      const action = actions[index]!;
      const prior = record.escalation.find((entry) => entry.action === action);
      if (prior && prior.outcome !== "requested") {
        if (prior.outcome === "exited") return;
        if (index < this.grace.length)
          await this.fencedEffect(record.invocationId, () =>
            this.options.clock.sleep(this.grace[index]!),
          );
        continue;
      }
      if (!prior) {
        record = this.mutate({
          type: "start_escalation",
          invocationId: record.invocationId,
          expectedRevision: record.revision,
          action,
          requestedAt: this.now(),
        });
      }
      let outcome: "running" | "exited" | "failed" = "failed";
      let detail: string | undefined;
      let signalEffectId: string | undefined;
      let selected: SelectedProcessBackend | undefined;
      try {
        selected = await this.fencedEffect(record.invocationId, (fence) =>
          reattestProcessBackend(
            this.options.registry,
            record.backendBinding!,
            fence,
          ),
        );
      } catch (error) {
        detail = error instanceof Error ? error.message : "Signal failed";
      }
      if (selected) {
        const signalled = await this.journaledEffect(
          record.invocationId,
          "backend_signal",
          (fence) =>
            selected.backend.signal(record.backendBinding!, action, fence),
        );
        const parsedOutcome = parseProcessSignalResult(signalled.result).state;
        signalEffectId = signalled.effectId;
        outcome =
          this.current(record.invocationId).state === "exited"
            ? "exited"
            : parsedOutcome;
      }
      record = this.current(record.invocationId);
      record = this.mutate({
        type: "finish_escalation",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        action,
        completedAt: this.now(),
        outcome,
        ...(detail ? { detail } : {}),
        ...(signalEffectId ? { effectId: signalEffectId } : {}),
      });
      if (record.state === "exited") return;
      if (outcome === "failed") {
        if (record.state === "cleanup_blocked")
          throw new SubprocessRuntimeError(
            "identity_mismatch",
            "Blocked backend authority could not be freshly revalidated.",
          );
        this.applyFailure(
          record,
          "identity_mismatch",
          "Backend authority could not be freshly revalidated before signal.",
        );
        throw new SubprocessRuntimeError(
          "identity_mismatch",
          "Backend authority could not be freshly revalidated.",
        );
      }
      if (outcome === "exited") return;
      if (index < this.grace.length)
        await this.fencedEffect(record.invocationId, () =>
          this.options.clock.sleep(this.grace[index]!),
        );
    }
  }

  private async reconcileBackend(
    invocationId: string,
    selected: SelectedProcessBackend,
    binding: DurableBackendBinding,
  ): Promise<ReturnType<typeof parseProcessReconciliation>> {
    const journal = await this.journaledEffect(
      invocationId,
      "backend_reconcile",
      (fence) => selected.backend.reconcile(binding, fence),
    );
    const reconciliation = parseProcessReconciliation(journal.result);
    const record = this.current(invocationId);
    this.mutate({
      type: "record_reconciliation",
      invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      effectId: journal.effectId,
      outcome: reconciliation.state,
      ...(reconciliation.state === "exited" &&
      reconciliation.exitCode !== undefined
        ? { exitCode: reconciliation.exitCode }
        : {}),
      ...(reconciliation.state === "exited" && reconciliation.signal
        ? { signal: reconciliation.signal }
        : {}),
    });
    return reconciliation;
  }

  private async reconcileRecord(
    snapshot: DurableSubprocessRecord,
  ): Promise<void> {
    let record = this.current(snapshot.invocationId);
    let output: ProcessOutputSession;
    try {
      if (record.outputPrepared) {
        const reopened = await this.journaledEffect(
          record.invocationId,
          "output_reopen",
          (fence) => this.options.outputs.reopen(record.outputOwnerId, fence),
        );
        output = reopened.result;
        record = this.current(record.invocationId);
        record = this.mutate({
          type: "record_output_reopen",
          invocationId: record.invocationId,
          expectedRevision: record.revision,
          at: this.now(),
          effectId: reopened.effectId,
        });
      } else {
        output = await this.fencedEffect(record.invocationId, (fence) =>
          this.options.outputs.prepare(record.outputOwnerId, fence),
        );
        record = this.mutate({
          type: "mark_output_prepared",
          invocationId: record.invocationId,
          expectedRevision: record.revision,
          at: this.now(),
        });
      }
    } catch (error) {
      throw new SubprocessRuntimeError(
        "outcome_unknown",
        "Output ownership could not be reopened.",
        { cause: error },
      );
    }
    if (
      record.state === "cleanup_blocked" &&
      !record.backendBinding &&
      record.result?.outcome === "launch_failed"
    ) {
      try {
        await this.cleanupOutput(record, output);
      } catch {
        this.blockPrelaunchCleanup(record);
        return;
      }
      record = this.current(record.invocationId);
      this.mutate({
        type: "settle_output_cleanup",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
      });
      return;
    }
    if (record.state === "cleanup_blocked" && record.backendBinding) {
      await this.recoverBoundCleanup(record, output);
      return;
    }
    if (record.state === "prepared") {
      try {
        await this.cleanupOutput(record, output);
      } catch {
        this.blockPrelaunchCleanup(record);
        return;
      }
      record = this.current(record.invocationId);
      this.mutate({
        type: "fail_launch",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        detail: "Restart found prepared intent.",
      });
      return;
    }
    if (record.state === "launching") {
      this.applyFailure(
        record,
        "orphaned",
        "Restart found launch without durable identity.",
      );
      return;
    }
    if (record.state === "exited" || record.state === "verifying_empty") {
      await this.finish(record, output);
      return;
    }
    if (!record.backendBinding)
      throw new SubprocessRuntimeError(
        "identity_mismatch",
        "Recoverable process lacks durable identity.",
      );
    let selected: SelectedProcessBackend;
    try {
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        reattestProcessBackend(
          this.options.registry,
          record.backendBinding!,
          fence,
        ),
      );
    } catch {
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        adoptProcessBackendAfterRestart(
          this.options.registry,
          record.backendBinding!,
          fence,
        ),
      );
      const prior = record.backendBinding;
      record = this.mutate({
        type: "adopt_backend",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        binding: {
          ...prior,
          registryId: selected.registryId,
          implementationGeneration: selected.implementationGeneration,
          implementationDigest: selected.implementationDigest,
          attestationVersion: selected.attestation.attestationVersion,
          attestationDigest: selected.attestationDigest,
        },
      });
    }
    const activeBinding = record.backendBinding!;
    const reconciliation = await this.reconcileBackend(
      record.invocationId,
      selected,
      activeBinding,
    );
    if (reconciliation.state === "identity_mismatch") {
      this.applyFailure(
        record,
        "identity_mismatch",
        "Backend reconciliation rejected identity.",
      );
      return;
    }
    if (reconciliation.state === "outcome_unknown") {
      this.applyFailure(
        record,
        "outcome_unknown",
        "Backend reconciliation outcome is unknown.",
      );
      return;
    }
    if (reconciliation.state === "running") {
      if (record.stopIntent) await this.escalate(record);
      let observation;
      let observationEffectId: string;
      try {
        const observed = await this.journaledEffect(
          record.invocationId,
          "backend_observe",
          (fence) =>
            selected.backend.observe(
              activeBinding,
              (stream, bytes) => output.write(stream, bytes, fence),
              fence,
            ),
        );
        observation = parseProcessObservation(observed.result);
        observationEffectId = observed.effectId;
      } catch (error) {
        throw new SubprocessRuntimeError(
          "outcome_unknown",
          "Recovered observation failed.",
          { cause: error },
        );
      }
      record = this.current(record.invocationId);
      record = this.mutate({
        type: "record_exit",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        effectId: observationEffectId,
        observation: {
          ...(observation.exitCode === undefined
            ? {}
            : { exitCode: observation.exitCode }),
          ...(observation.signal ? { signal: observation.signal } : {}),
          observedAt: this.now(),
        },
      });
    } else {
      record = this.current(record.invocationId);
      record = this.mutate({
        type: "record_exit",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        observation: {
          ...(reconciliation.exitCode === undefined
            ? {}
            : { exitCode: reconciliation.exitCode }),
          ...(reconciliation.signal ? { signal: reconciliation.signal } : {}),
          observedAt: this.now(),
        },
      });
    }
    await this.finish(record, output, selected);
  }

  private async recoverBoundCleanup(
    snapshot: DurableSubprocessRecord,
    output: ProcessOutputSession,
  ): Promise<void> {
    let record = this.current(snapshot.invocationId);
    let binding = requiredBinding(record);
    let selected: SelectedProcessBackend;
    try {
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        reattestProcessBackend(this.options.registry, binding, fence),
      );
    } catch {
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        adoptProcessBackendAfterRestart(this.options.registry, binding, fence),
      );
      record = this.mutate({
        type: "adopt_backend",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        at: this.now(),
        binding: {
          ...binding,
          registryId: selected.registryId,
          implementationGeneration: selected.implementationGeneration,
          implementationDigest: selected.implementationDigest,
          attestationVersion: selected.attestation.attestationVersion,
          attestationDigest: selected.attestationDigest,
        },
      });
      binding = requiredBinding(record);
    }
    let reconciliation = await this.reconcileBackend(
      record.invocationId,
      selected,
      binding,
    );
    if (reconciliation.state === "running" && record.stopIntent) {
      await this.escalate(record);
      record = this.current(record.invocationId);
      if (record.state !== "cleanup_blocked") return;
      binding = requiredBinding(record);
      selected = await this.fencedEffect(record.invocationId, (fence) =>
        reattestProcessBackend(this.options.registry, binding, fence),
      );
      reconciliation = await this.reconcileBackend(
        record.invocationId,
        selected,
        binding,
      );
    }
    if (reconciliation.state !== "exited") return;
    record = this.current(record.invocationId);
    record = this.mutate({
      type: "resume_blocked_exit",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      observation: {
        ...(reconciliation.exitCode === undefined
          ? {}
          : { exitCode: reconciliation.exitCode }),
        ...(reconciliation.signal ? { signal: reconciliation.signal } : {}),
        observedAt: this.now(),
      },
    });
    await this.finish(record, output, selected);
  }

  private async classifyReconciliationFailure(
    snapshot: DurableSubprocessRecord,
    error: unknown,
  ): Promise<void> {
    const record = this.options.store.readByInvocation(snapshot.invocationId);
    if (
      !record ||
      ![
        "prepared",
        "launching",
        "running",
        "stopping",
        "exited",
        "verifying_empty",
        "backend_unavailable",
      ].includes(record.state)
    )
      return;
    try {
      if (record.state === "prepared")
        this.mutate({
          type: "fail_launch",
          invocationId: record.invocationId,
          expectedRevision: record.revision,
          at: this.now(),
          detail: "Reconciliation failed before launch.",
        });
      else
        this.applyFailure(
          record,
          "outcome_unknown",
          error instanceof Error ? error.message : "Reconciliation failed.",
        );
    } catch {}
  }
  private async recoverBlockedRetry(
    snapshot: DurableSubprocessRecord,
  ): Promise<GenericProcessResult> {
    const owned = this.takeRecoveryOwnership(snapshot);
    if (!owned) return resultFromRecord(snapshot);
    try {
      await this.reconcileRecord(owned);
    } catch (error) {
      await this.classifyReconciliationFailure(owned, error);
    }
    return resultFromRecord(this.current(snapshot.invocationId));
  }
  private takeRecoveryOwnership(
    snapshot: DurableSubprocessRecord,
    activeEffectMode?: "join_active_observation",
  ): DurableSubprocessRecord | undefined {
    let record = this.current(snapshot.invocationId);
    const leaseIsLive =
      Date.parse(record.leaseExpiresAt) > this.options.clock.now().getTime();
    if (
      record.pendingEffects.length > 0 &&
      !this.canJoinActiveObservationForSignal(
        record,
        leaseIsLive,
        activeEffectMode,
      )
    )
      return undefined;
    if (leaseIsLive && record.ownerId !== this.ownerId) return undefined;
    if (leaseIsLive) {
      this.fences.set(record.invocationId, record.fencingToken);
      record = this.applyCurrent(record, (revision) => ({
        type: "renew_lease",
        invocationId: record.invocationId,
        expectedRevision: revision,
        at: this.now(),
        leaseExpiresAt: this.leaseExpiry(),
      }));
    } else {
      record = this.writer.apply({
        type: "takeover_lease",
        invocationId: record.invocationId,
        expectedRevision: record.revision,
        ownerId: this.ownerId,
        fencingToken: record.fencingToken + 1,
        at: this.now(),
        leaseExpiresAt: this.leaseExpiry(),
      });
    }
    this.fences.set(record.invocationId, record.fencingToken);
    return record;
  }
  private canJoinActiveObservationForSignal(
    record: DurableSubprocessRecord,
    leaseIsLive: boolean,
    mode?: "join_active_observation",
  ): boolean {
    if (
      mode !== "join_active_observation" ||
      !leaseIsLive ||
      record.state !== "running" ||
      record.stopIntent !== undefined ||
      record.ownerId !== this.ownerId ||
      this.fences.get(record.invocationId) !== record.fencingToken ||
      record.pendingEffects.length !== 1
    )
      return false;
    const effect = record.pendingEffects[0]!;
    return (
      effect.family === "backend_observe" &&
      effect.phase === "started" &&
      effect.ownerId === record.ownerId &&
      effect.fencingToken === record.fencingToken &&
      this.activeJournalEffects
        .get(record.invocationId)
        ?.get(effect.effectId) === "backend_observe"
    );
  }
  private requestStopLatest(
    invocationId: string,
    reason: "cancelled" | "timed_out",
  ): DurableSubprocessRecord {
    const record = this.current(invocationId);
    if (record.stopIntent) return record;
    return this.applyCurrent(record, (revision) => ({
      type: "request_stop",
      invocationId,
      expectedRevision: revision,
      at: this.now(),
      reason,
    }));
  }
  private applyCurrent(
    record: DurableSubprocessRecord,
    make: (revision: number) => DurableProcessCommand,
  ): DurableSubprocessRecord {
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        return this.mutate(make(record.revision));
      } catch (error) {
        if (
          !/revision conflict/i.test(
            error instanceof Error ? error.message : "",
          ) ||
          attempt === 2
        )
          throw error;
        record = this.current(record.invocationId);
      }
    }
    throw new Error("unreachable");
  }
  private mutate(command: DurableProcessCommand): DurableSubprocessRecord {
    const fencingToken = this.fences.get(command.invocationId);
    if (fencingToken === undefined)
      throw new Error("Process owner fencing authority is unavailable.");
    return this.writer.apply({
      ...command,
      ownerId: this.ownerId,
      fencingToken,
    });
  }
  private applyFailure(
    record: DurableSubprocessRecord,
    state:
      | "orphaned"
      | "identity_mismatch"
      | "backend_unavailable"
      | "outcome_unknown"
      | "cleanup_blocked",
    detail: string,
    cleanup?: ProcessCleanupStatus,
  ): DurableSubprocessRecord {
    record = this.current(record.invocationId);
    const result =
      state === "cleanup_blocked"
        ? terminalResult(record, this.now(), "cleanup_failed")
        : undefined;
    return this.mutate({
      type: "fail",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      state,
      detail,
      ...(cleanup ? { cleanup } : {}),
      ...(result ? { result } : {}),
    });
  }
  private async cleanupOutput(
    record: DurableSubprocessRecord,
    output: ProcessOutputSession,
  ): Promise<void> {
    await this.fencedEffect(record.invocationId, (fence) =>
      output.cleanup(fence),
    );
  }
  private async failBeforeLaunch(
    record: DurableSubprocessRecord,
    output: ProcessOutputSession,
    detail: string,
  ): Promise<void> {
    try {
      await this.cleanupOutput(record, output);
    } catch {
      this.blockPrelaunchCleanup(record);
      return;
    }
    record = this.current(record.invocationId);
    this.mutate({
      type: "fail_launch",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      detail,
    });
  }
  private blockPrelaunchCleanup(
    record: DurableSubprocessRecord,
  ): DurableSubprocessRecord {
    record = this.current(record.invocationId);
    const at = this.now();
    return this.mutate({
      type: "fail",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at,
      state: "cleanup_blocked",
      detail: "Recoverable output owner cleanup failed.",
      cleanup: {
        state: "failed",
        failedAt: at,
        code: "output_cleanup_failed",
        detail: "Recoverable output owner cleanup failed.",
      },
      result: { outcome: "launch_failed", finishedAt: at },
    });
  }
  private current(id: string): DurableSubprocessRecord {
    const record = this.options.store.readByInvocation(id);
    if (!record) throw new Error(`Unknown process invocation ${id}.`);
    return record;
  }
  private async observeExisting(
    invocationId: string,
  ): Promise<GenericProcessResult> {
    for (let attempt = 0; attempt < 1000; attempt += 1) {
      const record = this.options.store.readByInvocation(invocationId);
      if (!record)
        throw new SubprocessRuntimeError(
          "outcome_unknown",
          "Durable invocation disappeared.",
        );
      if (record.result) return resultFromRecord(record);
      if (
        ![
          "prepared",
          "launching",
          "running",
          "stopping",
          "exited",
          "verifying_empty",
          "backend_unavailable",
        ].includes(record.state)
      )
        throw new SubprocessRuntimeError(
          "outcome_unknown",
          `Durable invocation ended in ${record.state}.`,
        );
      await this.options.clock.sleep(1);
    }
    throw new SubprocessRuntimeError(
      "outcome_unknown",
      "Timed out observing the existing durable invocation.",
    );
  }
  private now(): string {
    return this.options.clock.now().toISOString();
  }
  private leaseExpiry(): string {
    return new Date(
      this.options.clock.now().getTime() + this.leaseMs,
    ).toISOString();
  }
  private renew(record: DurableSubprocessRecord): DurableSubprocessRecord {
    return this.mutate({
      type: "renew_lease",
      invocationId: record.invocationId,
      expectedRevision: record.revision,
      at: this.now(),
      leaseExpiresAt: this.leaseExpiry(),
    });
  }
  private fence(invocationId: string): ProcessEffectFence {
    const fencingToken = this.fences.get(invocationId);
    if (fencingToken === undefined)
      throw new Error("Process owner fencing authority is unavailable.");
    return Object.freeze({ ownerId: this.ownerId, fencingToken });
  }
  private assertFence(invocationId: string, fence: ProcessEffectFence): void {
    const record = this.current(invocationId);
    if (
      record.ownerId !== fence.ownerId ||
      record.fencingToken !== fence.fencingToken ||
      this.fences.get(invocationId) !== fence.fencingToken
    )
      throw new Error("Process owner fencing token is stale.");
  }
  private async fencedEffect<T>(
    invocationId: string,
    effect: (fence: ProcessEffectFence) => Promise<T>,
  ): Promise<T> {
    const fence = this.fence(invocationId);
    this.assertFence(invocationId, fence);
    const heartbeat = this.startHeartbeat(invocationId, fence);
    let result: T | undefined;
    let failure: unknown;
    try {
      result = await effect(fence);
    } catch (error) {
      failure = error;
    }
    const heartbeatFailure = await heartbeat.stop();
    this.assertFence(invocationId, fence);
    if (heartbeatFailure) throw heartbeatFailure;
    if (failure) throw failure;
    return result as T;
  }
  private async journaledEffect<T>(
    invocationId: string,
    family: DurableProcessEffectFamily,
    effect: (fence: ProcessEffectFence) => Promise<T>,
  ): Promise<{ readonly result: T; readonly effectId: string }> {
    const fence = this.fence(invocationId);
    this.assertFence(invocationId, fence);
    const effectId = safeOwnerId(`effect-${randomUUID()}`);
    const current = this.current(invocationId);
    this.mutate({
      type: "begin_effect",
      invocationId,
      expectedRevision: current.revision,
      at: this.now(),
      effectId,
      family,
      resolution: "commit",
    });
    const active =
      this.activeJournalEffects.get(invocationId) ??
      new Map<string, DurableProcessEffectFamily>();
    active.set(effectId, family);
    this.activeJournalEffects.set(invocationId, active);
    const heartbeat = this.startHeartbeat(invocationId, fence);
    let result: T | undefined;
    let failure: unknown;
    let rejected = false;
    try {
      result = await effect(fence);
    } catch (error) {
      rejected = true;
      failure = error;
    } finally {
      active.delete(effectId);
      if (active.size === 0) this.activeJournalEffects.delete(invocationId);
    }
    const heartbeatFailure = await heartbeat.stop();
    let fenceFailure: unknown;
    try {
      this.assertFence(invocationId, fence);
    } catch (error) {
      fenceFailure = error;
    }
    if (heartbeatFailure != null || fenceFailure !== undefined) {
      this.fences.delete(invocationId);
      throw heartbeatFailure ?? fenceFailure;
    }
    if (rejected) throw failure;
    const latest = this.current(invocationId);
    this.mutate({
      type: "complete_effect",
      invocationId,
      expectedRevision: latest.revision,
      at: this.now(),
      effectId,
      leaseExpiresAt: this.leaseExpiry(),
    });
    return { result: result as T, effectId };
  }
  private startHeartbeat(
    invocationId: string,
    fence: ProcessEffectFence,
