      if (stopped || failure) return;
      timer = setTimeout(() => {
        pending = Promise.resolve()
          .then(() => {
            this.assertFence(invocationId, fence);
            const current = this.current(invocationId);
            this.renew(current);
          })
          .catch((error) => {
            failure = error;
          })
          .finally(schedule);
      }, this.heartbeatMs);
      timer.unref?.();
    };
