        candidates.push(Promise.resolve({ reason: "cancelled" }));
      else
        candidates.push(
          new Promise((resolve) =>
            request.signal!.addEventListener(
              "abort",
              () => resolve({ reason: "cancelled" }),
              { once: true },
            ),
          ),
        );
    }
    if (request.deadline) {
      const delay = Math.max(
        0,
        request.deadline.getTime() - this.options.clock.now().getTime(),
