    options.leaseHeartbeatMs ?? Math.max(1, Math.floor(leaseDurationMs / 3)),
    "leaseHeartbeatMs",
  );
  if (leaseHeartbeatMs >= leaseDurationMs)
    throw new Error("Lease heartbeat must be shorter than the lease duration.");
