    registry,
    writer,
    store: storeKernel.store,
    stateKey: new Uint8Array(options.stateKey),
    grants,
    clock,
    environments,
    outputs,
    leaseDurationMs,
    leaseHeartbeatMs,
    ...(options.createLogicalProcessId
      ? { createLogicalProcessId: options.createLogicalProcessId }
      : {}),
    ...(options.escalationGraceMs
