  Object.defineProperties(runtimeObject, {
    invoke: {
      value: core.invoke.bind(core),
      enumerable: true,
      writable: false,
      configurable: false,
    },
    cancel: {
      value: core.cancel.bind(core),
      enumerable: true,
      writable: false,
      configurable: false,
    },
    reconcileStartup: {
      value: core.reconcileStartup.bind(core),
      enumerable: true,
      writable: false,
      configurable: false,
    },
